#include <linux/printk.h>
#include <linux/vmalloc.h>
#include <linux/atomic.h>

#define dprintk(level, fmt, ...) \
    do { if (current_debug_level >= level) \
            printk(KERN_DEBUG "vbuf-sg: " fmt, ##__VA_ARGS__); } while (0)

struct videobuf_mapping {
    atomic_t ref_count;
    // Assume other fields exist here
};

void videobuf_vm_open(struct vm_area_struct *vma)
{
    struct videobuf_mapping *mapping = vma->vm_private_data;

    if (!mapping)
        return;

    dprintk(1, "Opening vma for mapping at %p, ref count %d\n",
            mapping, atomic_read(&mapping->ref_count));
    atomic_inc(&mapping->ref_count);
}

void videobuf_vm_open(struct vm_area_struct *vma)
{
    struct videobuf_mapping *mapping = vma->vm_private_data;

    dprintk(1, "vbuf-sg: open\n");
    dprintk(3, "vbuf-sg: open: %p, ref %d\n", mapping, atomic_read(&mapping->ref));
    atomic_inc(&mapping->ref);
}

#include <linux/printk.h>
#include <linux/vmalloc.h>
#include <linux/kref.h>

#define dprintk(level, fmt, args...) \
    do { if (level <= current_debug_level) \
             printk("vbuf-sg: " fmt, ##args); } while (0)

int videobuf_vm_open(struct vm_area_struct *vma)
{
    struct videobuf_mapping *map = vma->vm_private_data;
    dprintk(2, "open: vma %p [map %p ref %d]\n",
            vma, map, kref_read(&map->ref));
    kref_get(&map->ref);
    return 0;
}

